mports -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500;700&display=swap\" rel=\"stylesheet\">\n\n  <!-- Tailwind CSS Framework -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['Plus Jakarta Sans', '-apple-system', 'BlinkMacSystemFont', 'sans-serif'],\n            mono: ['JetBrains Mono', 'monospace']\n          },\n          colors: {\n            bento: {\n              sky: '#0284c7',\n              cyan: '#06b6d4',\n              slate: '#0f172a',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <!-- Petite-Vue Reactive Engine -->\n  <script src=\"https://cdn.jsdelivr.net/npm/petite-vue@0.4.1/dist/petite-vue.iife.js\" defer></script>\n\n  <!-- Apple Bento Glassmorphism Custom CSS -->\n  <style>\n    body {\n      font-family: 'Plus Jakarta Sans', -apple-system, sans-serif;\n      background-color: #f8fafc;\n      color: #0f172a;\n      letter-spacing: -0.015em;\n    }\n    .bento-glass {\n      backdrop-filter: blur(24px);\n      -webkit-backdrop-filter: blur(24px);\n      background: rgba(255, 255, 255, 0.78);\n      border: 1px solid rgba(226, 232, 240, 0.85);\n    }\n    .dark .bento-glass {\n      background: rgba(15, 23, 42, 0.78);\n      border: 1px solid rgba(51, 65, 85, 0.85);\n    }\n    .floating-nav {\n      position: sticky;\n      top: 14px;\n      z-index: 50;\n      margin: 0 auto;\n      max-width: 82rem;\n      padding: 0 1rem;\n    }\n    ::-webkit-scrollbar { width: 6px; height: 6px; }\n    ::-webkit-scrollbar-track { background: #f1f5f9; }\n    ::-webkit-scrollbar-thumb { background: #93c5fd; border-radius: 9999px; }\n    ::-webkit-sc